'use strict';

// MODULES //

var serialize = require( '@stdlib/ndarray/base/serialize-meta-data' );
var getData = require( '@stdlib/ndarray/base/data-buffer' );
var addon = require( './../src/addon.node' );


// MAIN //

/**
* Divides elements of a one-dimensional single-precision floating-point ndarray by the corresponding elements of a second one-dimensional single-precision floating-point ndarray and assigns the results to the second ndarray.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a one-dimensional output ndarray.
*
* @private
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {ndarray} output ndarray
*
* @example
* var Float32Vector = require( '@stdlib/ndarray/vector/float32' );
*
* var x = new Float32Vector( [ 10.0, 12.0, 6.0, -4.0, 8.0 ] );
* var y = new Float32Vector( [ 2.0, 3.0, 2.0, -2.0, 4.0 ] );
*
* var out = sxdy( [ x, y ] );
* // returns <ndarray>[ 5.0, 4.0, 3.0, 2.0, 2.0 ]
*/
function sxdy( arrays ) {
	var x = arrays[ 0 ];
	var y = arrays[ 1 ];
	addon( getData( x ), serialize( x ), getData( y ), serialize( y ) );
	return y;
}


// EXPORTS //

module.exports = sxdy;
